const names = ALL_TOOLS.map(x => x.name);
const mcp = {};
for (const n of names.filter(n => n.startsWith("mcp__"))) {
  const parts = n.split("__");
  (mcp[parts[1]] ||= []).push(parts.slice(2).join("__"));
}
const native = names.filter(n => !n.startsWith("mcp__"));
text(JSON.stringify({mcp, native}, null, 2));

const [a,b,c] = await Promise.all([
  tools.mcp__potential_server__validate_potential({filepath:"Ni_u3.eam", element:"Ni"}),
  tools.mcp__potential_server__validate_potential({filepath:"Cu_u3.eam", element:"Cu"}),
  tools.mcp__structure_server__create_alloy({
    base_element:"Ni",
    alloy_element:"Cu",
    crystal_type:"fcc",
    lattice_param:3.5675,
    alloy_fraction:0.5,
    size:"8 8 16",
    output_filename:"nicu50_fcc.lmp"
  })
]);
for (const x of [a,b,c]) {
  if (x?.content) for (const item of x.content) {
    if (item.type === "text") text(item.text);
    else if (item.type === "image") image(item);
  }
}

const r = await tools.mcp__lammps_executor_server__run_lammps_batch_simulation({
  input_files:["in.nicu_relax","in.nicu_interface","in.nicu_heat"],
  timeout_per_file:6000
});
if (r?.content) for (const item of r.content) {
  if (item.type === "text") text(item.text);
  else if (item.type === "image") image(item);
}

const [plot, parsed] = await Promise.all([
  tools.mcp__visualization_server__plot_melting_analysis({
    log_file:"in.nicu_heat.log",
    output_image:"nicu_melting_analysis.png",
    plot_style:"comprehensive",
    system_name:"FCC Ni50Cu50 solid-liquid coexistence heating",
    num_atoms:4096,
    material:"Ni50Cu50"
  }),
  tools.mcp__results_server__parse_lammps_log({log_file:"in.nicu_heat.log"})
]);
for (const x of [plot,parsed]) if (x?.content) for (const item of x.content) {
  if (item.type === "text") text(item.text);
  else if (item.type === "image") image(item);
}
